[
  {
    "statement": "In Australia, creating long flexible habitats on subtidal artificial structures produced mixed effects on fish abundance, including seahorses, depending on species, prior fish presence, or survey week.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The creation of long flexible habitats on subtidal artificial structures in Australia produced mixed effects on fish species richness.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Seahorses were observed using long flexible habitats on subtidal artificial structures in Australia.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "In studies that included Australia, long flexible habitats showed mixed effects on invertebrate abundance, with these effects depending on species group, survey week, and habitat characteristics.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Studies in Australia and the Netherlands reported that long flexible habitats supported macroalgae and non-mobile invertebrate or fish species that were absent from surfaces without such habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Creating short flexible habitats in Australia yielded mixed effects on seahorse abundance, with the effects depending on the survey week.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Studies in Australia and France reported mixed effects from short flexible habitats on invertebrate abundance, with the outcomes depending on survey week, species group, habitat length, or site.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "One study found that short flexible habitats had no effect on mobile invertebrate abundance.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Overall in Australia, both short and long flexible habitats have shown mixed responses for fish and invertebrate populations.",
    "citations": [
      "3451",
      "3450"
    ]
  },
  {
    "statement": "Long flexible habitats in Australia are associated with use by seahorses.",
    "citations": [
      "3451",
      "3450"
    ]
  },
  {
    "statement": "Long flexible habitats in Australia are associated with the presence of species that are absent from control surfaces.",
    "citations": [
      "3451",
      "3450"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions (>50 mm) on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "There is no available evidence indicating desirable or harmful effects from creating large protrusions (>50 mm) on subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  }
]

[
  {
    "statement": "In estuaries in southeast Australia, transplanting oysters onto intertidal artificial structures supported macroalgae, mobile invertebrates, non-mobile invertebrates, and fish species that were absent from untreated structure surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The effects on combined macroalgae and invertebrate richness and diversity were mixed, depending on the site and the presence or size of grooves, small ridges, or ledges on surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study in Australia reported increased mobile invertebrate species richness on treated surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "For fishes, two of three Australian studies found no increase in species richness on treated surfaces.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One Australian study on fishes found mixed effects for species richness, depending on surface features and site.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One Australian study found no increase in the combined abundance of macroalgae and invertebrates.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Another Australian study found mixed effects for the abundance of combined macroalgae and invertebrates, depending on surface micro-features.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Invertebrate abundance responses were mixed across studies.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study found increased non-mobile invertebrate abundance and increased oyster recruit abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "One study found decreased barnacle abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Another study found increased abundance of oysters and mobile invertebrates.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Fish abundance generally did not increase in two of three Australian studies.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In one study, fish abundance was similar regardless of the size of grooves or ridges on the surface.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Survival of transplanted invertebrates, including oysters, varied with the species, site, and microhabitat features.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In one study, oyster survival was higher in grooves than on ridges.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In another study, the survival of invertebrates in grooves and ledges varied by site.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "A behavioral study in Australia found no increase in the time fishes interacted with surfaces after transplanting oysters and/or coralline algae.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "A behavioral study in Australia found no increase in the number of bites fishes took after transplanting oysters and/or coralline algae.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Benthic fishes took more bites from surfaces with transplanted oysters than from surfaces with both algae and oysters.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The results from the behavioral study on fish interaction held true regardless of the presence of grooves or ridges on the surfaces.",
    "citations": [
      "3472"
    ]
  }
]

[
  {
    "statement": "Across methods tested on intertidal artificial structures, creating rock pools most frequently increased overall species richness and diversity.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Nine of twelve replicated, controlled studies reported higher combined macroalgae, invertebrate, and/or fish richness and diversity in created pools than on flat surfaces.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Some studies found similar values for species richness and diversity in created rock pools as on flat surfaces.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating pit habitats on intertidal artificial structures often increased species richness and diversity.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Eight of twelve replicated controlled studies reported that creating pit habitats led to increases in combined macroalgae and invertebrate richness/diversity.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Two replicated controlled studies found no increase in species richness/diversity from creating pit habitats.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Two replicated controlled studies reported mixed effects from creating pit habitats, with results sometimes varying with pit size and arrangement.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "Creating groove habitats produced fewer consistent gains in species richness and diversity.",
    "citations": [
      "3473",
      "3464"
    ]
  },
  {
    "statement": "Three of six replicated controlled studies reported increases in combined richness and diversity from creating groove habitats.",
    "citations": [
      "3473",
      "3464"
    ]
  },
  {
    "statement": "Two replicated controlled studies found no increase in richness and diversity from creating groove habitats, while one reported mixed effects.",
    "citations": [
      "3473",
      "3464"
    ]
  },
  {
    "statement": "In some comparisons, created grooves supported higher species richness than adjacent small ledges or ridges.",
    "citations": [
      "3473",
      "3464"
    ]
  },
  {
    "statement": "Combining grooves with small protrusions, ridges, or ledges yielded increases in species richness and diversity in six of eleven replicated controlled studies.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Five replicated controlled studies reported mixed effects when combining grooves with small protrusions, ridges, or ledges, with results depending on the specific design and context.",
    "citations": [
      "3474"
    ]
  },
  {
    "statement": "Creating small ridges or ledges alone was a less effective method for increasing species richness.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "One of two randomized controlled studies found no increase in combined species richness from creating small ridges or ledges alone.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "Two studies found lower species richness on ridges and ledges than in grooves.",
    "citations": [
      "3464"
    ]
  },
  {
    "statement": "The creation of short flexible habitats reduced combined species richness in one randomized controlled study.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Creating small adjoining cavities or “swimthroughs” did not increase combined macroalgae and invertebrate richness in one replicated study.",
    "citations": [
      "3468"
    ]
  }
]

[
  {
    "statement": "Outcomes of creating ≤1 mm textured surfaces on intertidal structures varied across four European studies on open coasts, estuaries, and a port.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Overall combined macroalgae–invertebrate species richness showed mixed effects when textures were created alongside environmentally‑sensitive materials.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "The mixed effects on the species richness of macroalgae and invertebrates varied by texture type and site.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Macroalgal abundance did not increase in two replicated, paired, controlled studies in the Netherlands.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Invertebrate outcomes were mixed across four replicated, controlled studies.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "Two of the four replicated, controlled studies reported no increase in invertebrates.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "One study using environmentally‑sensitive materials found site‑dependent mixed effects on barnacle and mobile invertebrates.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "One study found increased barnacle abundance regardless of the texture type used.",
    "citations": [
      "3466"
    ]
  },
  {
    "statement": "In the study that found increased barnacle abundance, different textures supported different abundances of barnacles.",
    "citations": [
      "3466"
    ]
  }
]

[
  {
    "statement": "Creating large adjoining cavities or ‘swimthrough’ habitats larger than 100 mm increased overall fish species richness and abundance on and around structures.",
