  {
    "statement": "Creating long flexible habitats larger than 50 mm had mixed effects on fish species richness and on fish and seahorse abundance.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats were used by seahorses.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Creating short flexible habitats between 1 and 50 mm had mixed effects on seahorse abundance.",
    "citations": [
      "3450"
