  {
    "statement": "Managing or restricting harvesting around structures was associated with higher fish species richness.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "Managing or restricting harvesting around structures was associated with a different fish community composition, including species absent from unrestricted sites.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "Managing or restricting harvesting around structures was associated with higher seabream abundance.",
    "citations": [
      "3457"
