[
  {
    "statement": "In Israel, the UK, and Australia, using environmentally-sensitive materials like shell-concrete, quarried rock, or ECOncrete often altered the overall macroalgae and invertebrate community composition on artificial structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Some studies found no change or mixed effects on macroalgae and invertebrate community composition, depending on the material type and site.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The reported effects of using environmentally-sensitive materials on species richness and diversity were mixed.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Some cases involving ECOncrete with added texture, grooves, holes, pits, or ledges showed increases in species richness and diversity.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Other cases using quarried rock or alternative cement mixes did not increase species richness or diversity.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In the UK, one study found that recycled-cement concrete did not increase diatom species richness.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "For overall species abundance, several studies in Israel, the UK, and Australia found no increase or mixed responses when using environmentally-sensitive materials.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In one case, ECOncrete increased live cover and biomass on artificial structures.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Different concrete mixes supported differing amounts of cover and inorganic biomass.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "For algae, studies in Australia, Israel, and the UK reported no increases for several algal groups, such as brown, turf, coralline, and diatoms, when using quarried rock or recycled-cement concrete.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "There were some mixed outcomes and occasional increases for certain algal groups depending on the site and material used.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "For invertebrates, studies in Israel, the UK, and Australia reported mixed responses when using environmentally-sensitive materials.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In some cases, there were no increases for several sessile invertebrate groups with the use of quarried rock.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "A decrease for Spirorbid tubeworms was reported in one case.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The use of shell-concrete led to increased bivalve abundance.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Different ECOncrete and standard-concrete mixes supported different coral abundances.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "In Israel, one study reported mixed effects on fish abundances when using ECOncrete with added grooves, holes, and pits.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "The effects on fish abundances from using modified ECOncrete in Israel varied by species group.",
    "citations": [
      "3470"
    ]
  }
]

